"use client";

import CardValues from "@/component/ui/CardValues";
import {
  Box,
  FormControl,
  InputLabel,
  MenuItem,
  Select,
  Typography,
  useTheme,
} from "@mui/material";

import { LocalizationProvider } from "@mui/x-date-pickers/LocalizationProvider";
import { AdapterDayjs } from "@mui/x-date-pickers/AdapterDayjs";
import { DateCalendar } from "@mui/x-date-pickers/DateCalendar";

import "../globals.css";
import { useContext, useState } from "react";
import { Data } from "../context/Context";

import { PieChart, Cell, Pie, ResponsiveContainer, Tooltip } from "recharts";
import { DemoContainer } from "@mui/x-date-pickers/internals/demo";
import { DatePicker } from "@mui/x-date-pickers";
import dayjs, { Dayjs } from "dayjs";

function HeroSection() {
  const { totalStudents, emplpoyesCount } = useContext(Data);
  const theme = useTheme();
  const [activeCard, setActiveCard] = useState(0);
  const male = 825;
  const female = 861;
  const total = male + female;

  const malePercent = (male / total) * 100;
  const femalePercent = (female / total) * 100;

  const maleData = [
    { name: "Male", value: totalStudents?.data?.data?.male_students },
    { name: "Remaining", value: 100 - malePercent },
  ];

  const femaleData = [
    { name: "Female", value: totalStudents?.data?.data.female_students },
    { name: "Remaining", value: 100 - femalePercent },
  ];

  const toolTipCustomized = (
    <Box
      sx={{
        backgroundColor: "#222",
        color: "white",
        padding: "12px 18px",
        borderRadius: 3,
        boxShadow: "0 4px 15px rgba(0,0,0,0.15)",
      }}
    >
      <Typography
        sx={{
          fontSize: 18,
          fontWeight: 700,
        }}
      >
        Male: {totalStudents?.data?.data?.male_students}
      </Typography>
      <Typography
        sx={{
          fontSize: 18,
          fontWeight: 700,
        }}
      >
        female: {totalStudents?.data?.data?.female_students}
      </Typography>
    </Box>
  );
  const cards = [
    {
      title: "عدد الطلاب الكلي ",
      description: " إجمالي عدد الطلاب",
      fetchData: totalStudents?.data?.data.total_students,
      isPending: totalStudents?.isPending,
      image: "/statistic.png",
    },
    {
      title: "الموظفون الإداريون",
      description: " عدد الموظفون الإداريون بالأكاديمية",
      fetchData: emplpoyesCount?.data?.data.total_employees,
      isPending: emplpoyesCount?.isPending,
      image: "/rate-orange.png",
    },
    {
      title: "الطلاب المستفيدون من الحسم",
      description: " عدد المستفيدين في الأكاديمية",
      fetchData: 113,
      image: "/rate-orange.png",
    },
    {
      title: "الطلاب المضافون اليوم",
      description: " إجمالي الطلاب الجدد الذين تم تسجيلهم اليوم",
      fetchData: 0,
      image: "/rate-orange.png",
    },
  ];
  return (
    <Box>
      <Box
        sx={{
          marginTop: "20px",
          display: "grid",
          width: "100%",
          gridTemplateColumns: "repeat(auto-fill, minmax(261px, 1fr))",
          gap: "40px",
          flexWrap: "wrap",
          justifyItems: "center",
          minHeight: "300px",
        }}
      >
        {cards.map((card, index) => (
          <CardValues
            key={card.title}
            title={card.title}
            description={card.description}
            fetchData={card.fetchData}
            isPending={card.isPending}
            image={card.image}
            isActive={activeCard === index}
            onMouseEnter={() => setActiveCard(index)}
          />
        ))}
      </Box>
      <Box
        sx={{
          display: "flex",
          width: "100%",
          justifyContent: "center",
          alignItems: "flex-start",
          gap: "20px",
          flexWrap: "wrap",
          marginTop: "20px",
        }}
      >
        <Box
          sx={{
            flexGrow: {
              xs: "1",
              sm: "1",
              md: "1",
              lg: "0",
            },
            maxWidth: "100%",
            minWidth: "320px",
            height: "261px",
            padding: "10px",
            backgroundColor: "#ffff",
            border: "2px solid #eee",
            boxShadow: "0px 2px 4px rgba(0, 0, 0, 0.1)",
            borderRadius: "10px",
          }}
        >
          <Box
            sx={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              marginBottom: "10px",
            }}
          >
            <Typography>الدورة المتفوٌقة</Typography>
            <FormControl sx={{ width: "100px" }}>
              <InputLabel id="demo-simple-select-label">بكلوريا</InputLabel>
              <Select
                sx={{
                  backgroundColor: "#f0f0f0",
                  border: "none",
                  "&:hover": {
                    outline: "none",
                    border: "none",
                  },
                }}
                labelId="demo-simple-select-label"
                id="demo-simple-select"
                label="Age"
              >
                <MenuItem value={"علمي"}>علمي</MenuItem>
                <MenuItem value={"أدبي"}>أدبي</MenuItem>
                <MenuItem value={"تاسع"}>تاسع</MenuItem>
              </Select>
            </FormControl>
          </Box>
          <Typography
            component="div"
            sx={{
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              height: "100%",
              color: `${theme.palette.secondary.main}`,
              fontSize: "16px",
            }}
          >
            لا يوجد بيانات متوفرة حالياً
          </Typography>
        </Box>
        <Box
          sx={{
            flexGrow: {
              xs: "1",
              sm: "1",
              md: "1",
              lg: "0",
            },
            minWidth: "350px",
            maxWidth: "100%",
            borderRadius: "10px",
            height: "520px",
            backgroundColor: "#eee",
            border: "2px solid #eee",
          }}
        >
          <Box
            sx={{
              height: 520,
              borderRadius: 4,
              p: 3,
              backgroundColor: "#fff",
            }}
          >
            <Typography
              sx={{
                fontSize: 22,
                fontWeight: 600,
                textAlign: "right",
              }}
            >
              الطلاب
            </Typography>

            <Box
              sx={{
                height: 380,
                position: "relative",
              }}
            >
              <ResponsiveContainer height="100%">
                <PieChart width={320} height={520}>
                  {/* Outer ring - Male */}
                  <Pie
                    data={maleData}
                    dataKey="value"
                    cx="50%"
                    cy="50%"
                    innerRadius={110}
                    outerRadius={145}
                    startAngle={0}
                    activeShape={{
                      fill: "#5ba3de",
                    }}
                    endAngle={180}
                    paddingAngle={0}
                    stroke="white"
                    strokeWidth={3}
                  >
                    <Cell fill="#5BC0DE" />
                    <Cell fill="#EEEEEE" />
                  </Pie>

                  {/* Inner ring - Female */}
                  <Pie
                    data={femaleData}
                    dataKey="value"
                    cx="50%"
                    cy="50%"
                    innerRadius={75}
                    outerRadius={108}
                    startAngle={0}
                    activeShape={{
                      fill: "#d69a9a",
                    }}
                    endAngle={180}
                    paddingAngle={0}
                    stroke="white"
                    strokeWidth={3}
                  >
                    <Cell fill="#D69AA5" />
                    <Cell fill="#EEEEEE" />
                  </Pie>
                  <Tooltip content={toolTipCustomized} />
                </PieChart>
              </ResponsiveContainer>

              {/* Center text */}
              <Box
                sx={{
                  position: "absolute",
                  top: "50%",
                  left: "50%",
                  transform: "translate(-50%, -50%)",
                  textAlign: "center",
                }}
              >
                <Typography fontWeight={600}>المجموع الكلي</Typography>

                <Typography
                  sx={{
                    fontSize: 24,
                    fontWeight: 700,
                  }}
                >
                  {total}
                </Typography>
              </Box>
            </Box>

            {/* Legend */}
            <Box
              sx={{
                display: "flex",
                justifyContent: "center",
                gap: 8,
                mt: 1,
              }}
            >
              <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                <Box
                  sx={{
                    width: 24,
                    height: 24,
                    borderRadius: "50%",
                    backgroundColor: "#D69AA5",
                  }}
                />

                <Typography>الإناث</Typography>
              </Box>

              <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                <Box
                  sx={{
                    width: 24,
                    height: 24,
                    borderRadius: "50%",
                    backgroundColor: "#5BC0DE",
                  }}
                />

                <Typography>الذكور</Typography>
              </Box>
            </Box>
          </Box>
        </Box>
        <Box
          sx={{
            flexGrow: {
              xs: "1",
              sm: "1",
              md: "1",
              lg: "0",
            },
            minWidth: "320px",
            height: "261px",
            border: "2px solid #eee",
          }}
        >
          <LocalizationProvider dateAdapter={AdapterDayjs}>
            <DemoContainer components={["DatePicker"]}>
              <DatePicker label="Controlled picker" />
            </DemoContainer>
          </LocalizationProvider>
        </Box>
      </Box>
    </Box>
  );
}

export default HeroSection;
